import { AuthActionTypes, IAuthDispatch } from "../types/auth-types";
import MyParksService from "../services/myparks-service";
import { toIUser } from "./auth-user-mapper";

export const fetchProducts = async (dispatch: IAuthDispatch) => {
  dispatch({ type: AuthActionTypes.FETCH_PRODUCTS_REQUEST });

  try {
    const result = await MyParksService.fetchProducts();
    dispatch({ type: AuthActionTypes.FETCH_PRODUCTS_SUCCESS, payload: { userProducts: result } });
    return result;
  } catch (e: unknown) {
    console.error(e);
    dispatch({ type: AuthActionTypes.FETCH_PRODUCTS_FAILURE, payload: { error: e as string } });
    return null;
  }
};

