export const fetchContactlessOrderDetails = async (dispatch: IAuthDispatch, orderId: string) => {
  dispatch({ type: AuthActionTypes.FETCH_CONTACTLESS_DETAILS_REQUEST, payload: { orderId } });

  try {
    const response = await MyParksService.getContactlessOrderDetails(orderId);
    dispatch({ type: AuthActionTypes.FETCH_CONTACTLESS_DETAILS_SUCCESS, payload: { orderId, response } });
  } catch (e) {
    dispatch({ type: AuthActionTypes.FETCH_CONTACTLESS_DETAILS_FAILURE, payload: { orderId } });
  }
};

export const fetchSession = (dispatch: IAuthDispatch) => {
  dispatch({ type: AuthActionTypes.FETCH_SESSION_REQUEST });

  MyParksService.fetchSession()
    .then((response) => {
      const responseInfo = {
        antiCsrfToken: response?.antiCsrfToken || undefined,
        cookieString: response?.cookieString || undefined,
        isLoggedIn: response?.hasLoggedIn || undefined,
      };

      dispatch({ type: AuthActionTypes.SESSION_UPDATED, payload: responseInfo });
    })
    .catch((e) => {
      dispatch({ type: AuthActionTypes.FETCH_SESSION_FAILURE, payload: null });
    });
};

// Reused when several components request the user in the same render commit,
// before the isFetchingUser flag has updated, so only one request is made.
let fetchUserPromise: Promise<void> | null = null;

export const fetchUser = (dispatch: IAuthDispatch) => {
  if (fetchUserPromise) {
    return fetchUserPromise;
  }

  dispatch({ type: AuthActionTypes.FETCH_USER_REQUEST });

  fetchUserPromise = MyParksService.getUser()
    .then((response) => {
      dispatch({ type: AuthActionTypes.FETCH_USER_SUCCESS, payload: { user: toIUser(response) } });
    })
    .catch((e) => {
      console.error(e);
      dispatch({ type: AuthActionTypes.FETCH_USER_FAILURE });
    })
    .finally(() => {
      fetchUserPromise = null;
    });

  return fetchUserPromise;
};
