import { ContactMethod, ContactMethodResponseItem, UserResponseItem } from "@parksandresorts/myparks-types";
import { IUser } from "../types/auth-types";

/**
 * A user can have several contact methods of the same type (e.g. two emails),
 * with one marked as primary per type. Pick the primary one, or fall back to
 * the first of that type.
 */
const findContactValue = (contactMethods: Array<ContactMethodResponseItem>, type: ContactMethod): string => {
  const ofType = contactMethods.filter((contactMethod) => contactMethod.contactMethod === type);
  const primary = ofType.find((contactMethod) => contactMethod.isPrimary);

  return (primary ?? ofType[0])?.value ?? "";
};

/**
 * Maps the /user response to the IUser shape the auth state has always held.
 * The property fields are PascalCase for parity with the old /session response,
 * so no consumers need to change. Replacing UserProperty with the generated
 * PublicPropertyResponseItem type is a breaking change tracked separately.
 */
export const toIUser = (response: UserResponseItem): IUser => {
  const properties = response.properties?.map((property) => ({
    PropertyType: property.propertyType,
    ExpiresOn: property.expiresOn ?? null,
    Comment: property.comment ?? null,
  }));

  return {
    altId: response.altId,
    firstName: response.firstName ?? "",
    lastName: response.lastName ?? "",
    birthDate: response.birthDate ?? "",
    email: findContactValue(response.contactMethods, ContactMethod.EMAIL),
    phoneNo: findContactValue(response.contactMethods, ContactMethod.MOBILE_PHONE),
    properties,
  };
};
